const items = $input.all();

// --------------------------------------------------
// KNOWN AUTOMATION / BOT ACTOR IDs
// --------------------------------------------------
// هذه IDs لبوتات / رسائل آلية معروفة عندنا.
// ممنوع أي واحد منهم يوقف الـ AI.
const AUTOMATION_ACTOR_IDS = [
  'AUTOMATION_ACTOR_ID_1',
  'AUTOMATION_ACTOR_ID_2',
];

return items.map((item) => {
  const body = item.json.body ?? item.json;

  const action = body.action ?? '';
  const actorType = body.actor?.actor_type ?? '';
  const actorId = body.actor?.actor_id ?? '';

  let eventType = 'ignore';
  let conversation = null;
  let message = null;
  let user = null;

  // --------------------------------------------------
  // 1) MESSAGE CREATED
  // --------------------------------------------------
  if (action === 'message_create') {
    message = body.data?.message ?? {};

    const messageActorId =
      message?.actor_id ??
      actorId ??
      '';

    const orgActorId =
      message?.org_actor_id ??
      null;

    // -----------------------------
    // Customer message
    // -----------------------------
    if (actorType === 'user') {
      eventType = 'customer_message';

    // -----------------------------
    // Agent / Bot / AI message
    // -----------------------------
    } else if (actorType === 'agent') {

      const isKnownAutomation =
        AUTOMATION_ACTOR_IDS.includes(messageActorId);

      // الموظف البشري الحقيقي يظهر معه org_actor_id
      const isHumanAgent =
        Boolean(orgActorId) &&
        !isKnownAutomation;

      if (isKnownAutomation) {
        // بوت Freshchat / Freshdesk أو AI/n8n
        eventType = 'automated_agent_message';

      } else if (isHumanAgent) {
        // موظف بشري حقيقي
        eventType = 'human_agent_message';

      } else {
        // Agent غير معروف وما عنده org_actor_id.
        // نعامله كرسالة آلية حتى لا نوقف الـ AI بالغلط
        // إذا ظهر بوت جديد مستقبلًا.
        eventType = 'automated_agent_message';
      }

    } else {
      eventType = 'unknown_message';
    }

  // --------------------------------------------------
  // 2) ASSIGN TO ME / CONVERSATION ASSIGNMENT
  // --------------------------------------------------
  } else if (action === 'conversation_assignment') {
    conversation =
      body.data?.assignment?.conversation ??
      {};

    const assignorId =
      body.data?.assignment?.assignor_id ??
      actorId ??
      '';

    // إذا assignment جاء من automation معروف لا نوقف AI.
    // غير ذلك نعتبره تدخل موظف بشري.
    if (AUTOMATION_ACTOR_IDS.includes(assignorId)) {
      eventType = 'automated_assignment';
    } else {
      eventType = 'agent_assignment';
    }

  // --------------------------------------------------
  // 3) RESOLVE
  // --------------------------------------------------
  } else if (action === 'conversation_resolution') {
    conversation =
      body.data?.resolve?.conversation ??
      {};

    user =
      body.data?.resolve?.user ??
      {};

    eventType = 'conversation_resolved';

  // --------------------------------------------------
  // 4) REOPEN
  // --------------------------------------------------
  } else if (action === 'conversation_reopen') {
    conversation =
      body.data?.reopen?.conversation ??
      {};

    const reopenerId =
      body.data?.reopen?.reopener_id ??
      actorId ??
      '';

    if (actorType === 'user') {
      eventType = 'customer_reopen';

    } else if (actorType === 'agent') {

      if (AUTOMATION_ACTOR_IDS.includes(reopenerId)) {
        eventType = 'automated_reopen';
      } else {
        eventType = 'agent_reopen';
      }

    } else {
      eventType = 'unknown_reopen';
    }
  }

  // --------------------------------------------------
  // Conversation ID
  // --------------------------------------------------
  const conversationId =
    message?.conversation_id ??
    conversation?.conversation_id ??
    null;

  // --------------------------------------------------
  // Message Parts
  // --------------------------------------------------
  const messageParts =
    message?.message_parts ??
    [];

  const messageText =
    messageParts
      .map((part) => part.text?.content)
      .filter(Boolean)
      .join('\n') || null;

  // --------------------------------------------------
  // Images
  // --------------------------------------------------
  const imageUrls =
    messageParts
      .map((part) => part.image?.url)
      .filter(Boolean);

  // --------------------------------------------------
  // AI ACTION
  // --------------------------------------------------
  let aiAction = 'ignore';

  // رسالة العميل:
  // افحص هل AI شغال أو موقوف
  if (eventType === 'customer_message') {
    aiAction = 'check_if_ai_active';
  }

  // فقط تدخل بشري حقيقي يوقف AI
  if (
    eventType === 'human_agent_message' ||
    eventType === 'agent_assignment' ||
    eventType === 'agent_reopen'
  ) {
    aiAction = 'pause_ai';
  }

  // Resolve يرجع AI للعمل
  if (
    eventType === 'conversation_resolved' ||
    eventType === 'customer_reopen'
  ) {
    aiAction = 'activate_ai';
  }

  // هذه الحالات كلها تبقى ignore:
  //
  // automated_agent_message
  // automated_assignment
  // automated_reopen
  //
  // يعني البوتات وردود AI/n8n
  // ممنوع تغير حالة الـ AI.

  // --------------------------------------------------
  // OUTPUT
  // --------------------------------------------------
  return {
    json: {
      request_id: body.request_id ?? null,
      action,
      action_time: body.action_time ?? null,

      event_type: eventType,
      ai_action: aiAction,

      actor_type: actorType,
      actor_id: actorId,

      // مهم للتشخيص ومعرفة البشري من الآلي
      org_actor_id:
        message?.org_actor_id ??
        conversation?.assigned_org_agent_id ??
        null,

      conversation_id: conversationId,

      conversation_status:
        conversation?.status ??
        null,

      conversation_internal_id:
        conversation?.conversation_internal_id ??
        message?.freshchat_conversation_id ??
        null,

      user_id:
        message?.user_id ??
        conversation?.user_id ??
        user?.id ??
        null,

      message_id:
        message?.id ??
        null,

      message_type:
        message?.message_type ??
        null,

      message_text: messageText,
      message_parts: messageParts,

      image_urls: imageUrls,
      image_count: imageUrls.length,
      has_images: imageUrls.length > 0,

      channel_id:
        message?.channel_id ??
        conversation?.channel_id ??
        null,

      assigned_agent_id:
        conversation?.assigned_agent_id ??
        body.data?.assignment?.to_agent_id ??
        null,

      customer_phone:
        user?.phone ??
        null,

      customer_name:
        user?.first_name ??
        null,

      original_event: body,
    },
  };
});

const rows = $input.all().map(item => item.json);

if (rows.length === 0) {
  return [];
}

// الرسالة التي شغّلت هذا الـ Execution
const currentMessageId = String(
  $('Build Customer Context').first().json.message_id ?? ''
);

// --------------------------------------------------
// تحويل وقت Supabase إلى timestamp
// received_at مثال:
// 2026-08-09T11:02:45.830+00:00
// --------------------------------------------------
function parseTime(value) {
  if (!value) return null;

  const time = Date.parse(String(value));
  return Number.isFinite(time) ? time : null;
}

// --------------------------------------------------
// تحديد أحدث صورة حسب received_at
// وإذا تساوى الوقت نستخدم id
// --------------------------------------------------
const latestRow = rows.reduce((latest, row) => {
  const latestTime = parseTime(latest.received_at);
  const rowTime = parseTime(row.received_at);

  if (latestTime === null && rowTime !== null) {
    return row;
  }

  if (latestTime !== null && rowTime === null) {
    return latest;
  }

  if (latestTime === null && rowTime === null) {
    return Number(row.id) > Number(latest.id)
      ? row
      : latest;
  }

  if (rowTime > latestTime) {
    return row;
  }

  if (
    rowTime === latestTime &&
    Number(row.id) > Number(latest.id)
  ) {
    return row;
  }

  return latest;
});

// فقط Execution الخاص بأحدث صورة يكمل
if (String(latestRow.message_id) !== currentMessageId) {
  return [];
}

// --------------------------------------------------
// نأخذ فقط الصور القريبة من أحدث صورة
// حتى الصور القديمة غير المعالجة لا تدخل في Batch جديد
// --------------------------------------------------
const latestTime = parseTime(latestRow.received_at);

const BATCH_WINDOW_MS = 60 * 1000;

const batchRows = rows.filter(row => {
  const rowTime = parseTime(row.received_at);

  if (latestTime === null || rowTime === null) {
    return String(row.message_id) === String(latestRow.message_id);
  }

  return (
    latestTime - rowTime >= 0 &&
    latestTime - rowTime <= BATCH_WINDOW_MS
  );
});

// --------------------------------------------------
// ترتيب صفوف الدفعة من الأقدم إلى الأحدث
// حتى نجمع النصوص بالترتيب الصحيح
// --------------------------------------------------
const sortedBatchRows = [...batchRows].sort((a, b) => {
  const timeA = parseTime(a.received_at);
  const timeB = parseTime(b.received_at);

  if (timeA === null && timeB === null) {
    return Number(a.id) - Number(b.id);
  }

  if (timeA === null) return -1;
  if (timeB === null) return 1;

  if (timeA !== timeB) {
    return timeA - timeB;
  }

  return Number(a.id) - Number(b.id);
});

// --------------------------------------------------
// تجميع روابط الصور
// --------------------------------------------------
const imageUrls = [];

for (const row of sortedBatchRows) {
  let urls = row.image_urls;

  if (typeof urls === 'string') {
    try {
      urls = JSON.parse(urls);
    } catch {
      urls = urls ? [urls] : [];
    }
  }

  if (Array.isArray(urls)) {
    imageUrls.push(...urls);
  }
}

// --------------------------------------------------
// تجميع نصوص نفس الـ Batch
// --------------------------------------------------
const textParts = sortedBatchRows
  .map(row => String(row.message_text ?? '').trim())
  .filter(text => text.length > 0);

const batchMessageText = textParts.join('\n');

return [
  {
    json: {
      conversation_id: latestRow.conversation_id,
      conversation_internal_id: latestRow.conversation_internal_id,
      user_id: latestRow.user_id,
      customer_phone: latestRow.customer_phone,

      image_urls: [...new Set(imageUrls)],

      batch_message_text: batchMessageText,

      buffered_message_ids: sortedBatchRows.map(row => row.message_id),

      // بدل row_number تبع Google Sheets
      buffer_ids: sortedBatchRows.map(row => row.id)
    }
  }
];

const draft = $input.first().json;
const newBatch = $('Keep Latest Image Batch').first().json;

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [parsed];
    } catch {
      return [value];
    }
  }

  return [value];
}

const oldImages = toArray(draft.image_urls);
const newImages = toArray(newBatch.image_urls);

const mergedImages = [...new Set([
  ...oldImages,
  ...newImages
])];

return [{
  json: {
    row_number: draft.row_number,
    issue_id: draft.issue_id,
    image_urls: JSON.stringify(mergedImages)
  }
}];

