(() => {
  const context = $('Build Customer Context').first().json;

  // ==================================================
  // الرسالة والصور من الـWebhook الحالي
  // تستخدم كـ fallback للرسائل العادية
  // ==================================================

  const currentMessage = String(
    context.customer_message || ''
  ).trim();

  const currentImages = Array.isArray(context.image_urls)
    ? context.image_urls
    : [];

  // ==================================================
  // نحاول أخذ الـBatch الكامل إذا مر التنفيذ بمسار الصور
  // ==================================================

  let batchMessage = '';
  let batchImages = [];

  try {
    const batch = $('Keep Latest Image Batch').first().json;

    batchMessage = String(
      batch.batch_message_text || ''
    ).trim();

    batchImages = Array.isArray(batch.image_urls)
      ? batch.image_urls
      : [];
  } catch (e) {
    // الرسالة لم تمر بمسار الصور
  }

  // إذا كان عندنا Batch صور نستخدم بياناته.
  // وإذا كانت رسالة عادية نستخدم Build Customer Context.
  const message = batchMessage || currentMessage;

  const images = batchImages.length > 0
    ? batchImages
    : currentImages;

  // ==================================================
  // هل يوجد Issue Draft حالي بحالة collecting؟
  // ==================================================

  let hasCollectingIssue = false;

  try {
    const draft = $('Get Collecting Issue').first().json;

    hasCollectingIssue =
      draft &&
      draft.row_number !== undefined;
  } catch (e) {
    hasCollectingIssue = false;
  }

  // ==================================================
  // يوجد Issue Draft حقيقي مفتوح
  // ==================================================

  if (hasCollectingIssue) {

    if (message && images.length) {
      return (
        message +
        '\n\n[العميل أرسل صورة أو أكثر، وتمت إضافة الصور إلى مسودة المشكلة الحالية. لا تطلب منه إعادة إرسالها، وتابع جمع المعلومات الناقصة للمشكلة.]'
      );
    }

    if (message) {
      return message;
    }

    if (images.length) {
      return '[العميل أرسل صورة أو أكثر وتمت إضافتها إلى مسودة المشكلة الحالية. لا تطلب منه إعادة إرسالها، وتابع جمع المعلومات الناقصة للمشكلة.]';
    }
  }

  // ==================================================
  // لا يوجد Issue Draft
  // ==================================================

  if (message && images.length) {
    return (
      message +
      '\n\n[العميل أرسل صورة أو أكثر مع هذه الرسالة. لا تفترض أن الصورة شكوى أو مشكلة من تلقاء نفسها. افهم الغرض من كلام العميل وسياق المحادثة. لا تطلب منه إعادة إرسال الصورة الحالية.]'
    );
  }

  if (message) {
    return message;
  }

  if (images.length) {
    return '[العميل أرسل صورة أو أكثر بدون نص. لا تفترض أنها شكوى أو مشكلة. إذا لم يكن الغرض واضحًا، اسأل العميل باختصار ماذا يريد بخصوص الصورة، ولا تطلب منه إعادة إرسال الصورة الحالية.]';
  }

  return 'وصلت رسالة من العميل دون نص أو صور قابلة للقراءة.';
})()
}}

