(() => {

  const issueState = String(
    $fromAI(
      'save_issue_id',
      `MANDATORY ISSUE ID DECISION.

Use ONLY the result returned by Get Current Issue Draft in the CURRENT customer turn.

If Get Current Issue Draft returned status = collecting:
Return ONLY the exact existing issue_id from that result.
Do not modify it.
Do not generate a new ID.
Do not return NEW.

If Get Current Issue Draft returned status = pending:
Return exactly BLOCK.

If Get Current Issue Draft genuinely returned NO active issue:
Return exactly NEW.

Never invent an issue_id.
Never use conversation memory as the source of issue_id.`,
      'string',
      ''
    ) || ''
  ).trim();


  // Existing pending issue must block writes
  if (issueState === 'BLOCK') {
    throw new Error(
      'Active pending issue exists. Save Issue Draft is blocked.'
    );
  }


  // Existing collecting issue → SAME ROW
  if (issueState.startsWith('issue_')) {
    return issueState;
  }


  // Only genuine "no active issue" may create a new ID
  if (issueState === 'NEW') {

    const conversationId = String(
      $('Build Customer Context').first().json.conversation_id || ''
    ).trim();

    if (!conversationId) {
      throw new Error(
        'conversation_id is required to create a new issue_id.'
      );
    }

    const executionId = String(
      $execution.id || ''
    ).trim();

    if (!executionId) {
      throw new Error(
        'execution_id is required to create a new issue_id.'
      );
    }

    return `issue_${conversationId}_${executionId}`;
  }


  throw new Error(
    'Invalid save_issue_id decision. Expected exact existing issue_id, NEW, or BLOCK.'
  );

})()
}}

