  }

  const existingTicketType = String(
    currentDraft?.ticket_type || ''
  ).trim();

  const allowedTypes = [
    'Complaint',
    'Customer Request'
  ];

  // إذا الـDraft الحالية فيها نوع معتمد مسبقًا
  // نحافظ عليه ولا نطلب من الـAI إعادة تصنيفه
