    return existingTicketType;
  }

  // إذا Issue جديدة، نخلي الـAgent يحدد النوع
  const aiTicketType = String(
    $fromAI(
      'ticket_type',
      'Return exactly one approved Freshdesk ticket type for this issue: Complaint or Customer Request. Use Complaint for an actual customer problem, complaint, damage, missing item, quality issue, or service failure. Use Customer Request only for a customer request or service request that is not a complaint. Never invent another value.',
      'string',
      ''
    ) || ''
  ).trim();

  if (allowedTypes.includes(aiTicketType)) {
    return aiTicketType;
  }

  throw new Error(
    'ticket_type must be exactly Complaint or Customer Request.'
  );
})()
}}

