(() => {
  let currentDraft = null;

  try {
    currentDraft = $('Get Current Issue Draft').first().json;
  } catch (e) {
    currentDraft = null;
  }

  const existingTicketType = String(
    currentDraft?.ticket_type || ''
  ).trim();

  const existingLevel1 = String(
    currentDraft?.level_1 || ''
  ).trim();

  if (existingTicketType === 'Customer Request') {
    return '';
  }

  const allowedLevel1 = [
    'OPS',
    'Logistic',
    'Customer Service',
    'IT Team',
    'Company Policies'
  ];

  if (existingLevel1) {
    if (!allowedLevel1.includes(existingLevel1)) {
      throw new Error(
        `Invalid existing level_1: ${existingLevel1}`
      );
    }

    return existingLevel1;
  }

  const aiLevel1 = String(
    $fromAI(
      'level_1',
      'For a Complaint, return exactly one approved Level 1 value: OPS, Logistic, Customer Service, IT Team, or Company Policies. Follow the complaint taxonomy and routing rules in the system prompt. For Customer Request return an empty string. Never invent, translate, rename, or approximate a classification.',
      'string',
      ''
    ) || ''
  ).trim();

  if (!aiLevel1) {
    return '';
  }

  if (!allowedLevel1.includes(aiLevel1)) {
    throw new Error(
      `Invalid level_1 returned by AI: ${aiLevel1}`
    );
  }

  return aiLevel1;
})()
}}

