={{
(() => {

  // ==================================================
  // Parse image values safely
  // ==================================================

  function parseImages(value) {

    if (Array.isArray(value)) {
      return value;
    }

    if (value === null || value === undefined) {
      return [];
    }

    const trimmed = String(value).trim();

    if (!trimmed) {
      return [];
    }

    try {

      const parsed = JSON.parse(trimmed);

      if (Array.isArray(parsed)) {
        return parsed;
      }

      if (parsed) {
        return [parsed];
      }

      return [];

    } catch (e) {

      return [trimmed];

    }
  }


  // ==================================================
  // Normalize image URL
  // ==================================================

  function normalizeUrl(value) {

    let url = String(value || '').trim();

    if (!url) {
      return '';
    }

    // Supports Markdown format:
    // [https://example.com/image.jpg](https://example.com/image.jpg)
    const markdownMatch =
      url.match(/\((https?:\/\/[^)]+)\)/i);

    if (markdownMatch && markdownMatch[1]) {
      url = markdownMatch[1].trim();
    }

    url = url
      .replace(/^["']+|["']+$/g, '')
      .trim();

    if (!/^https?:\/\//i.test(url)) {
      return '';
    }

    return url;
  }


  // ==================================================
  // EXISTING images from current collecting Issue Draft
  //
  // IMPORTANT:
  // Let the Agent pass the exact images it JUST received
  // from Get Current Issue Draft.
  // ==================================================

  const existingImagesRaw = String(
    $fromAI(
      'save_issue_existing_image_urls',
      `Return ONLY the complete image_urls JSON array from the SAME active collecting Issue Draft returned by Get Current Issue Draft in the CURRENT Agent execution.

CRITICAL PRESERVATION RULE:

If Get Current Issue Draft returned status = collecting and its image_urls already contains one or more images, return EVERY existing image URL exactly as stored.

A customer sending a text-only message, phone number, clarification, or any other information MUST NEVER cause existing images to be removed.

If existing images are present:
NEVER return [].

Do not invent image URLs.
Do not shorten image URLs.
Do not alter image URLs.
Do not omit any existing image URL.

Return a JSON array only.

Example:
["https://example.com/1.jpg","https://example.com/2.jpg"]

Return exactly [] ONLY if Get Current Issue Draft genuinely returned no existing images.`,
      'string',
      '[]'
    ) || '[]'
  ).trim();


  let existingImages =
    parseImages(existingImagesRaw);


  // ==================================================
  // NEW images from current image batch
  // ==================================================

  let newImages = [];

  try {

    const batch =
      $('Keep Latest Image Batch').first().json;

    newImages =
      parseImages(batch.image_urls);

  } catch (e) {

    newImages = [];

  }


  // ==================================================
  // Fallback for images received in current context
  // ==================================================

  if (newImages.length === 0) {

    try {

      const context =
        $('Build Customer Context').first().json;

      newImages =
        parseImages(context.image_urls);

    } catch (e) {

      newImages = [];

    }
  }


  // ==================================================
  // Preserve existing + add new + remove duplicates
  // ==================================================

  const allImages =
    existingImages.concat(newImages);

  const uniqueImages = [
    ...new Set(
      allImages
        .map(normalizeUrl)
        .filter(Boolean)
    )
  ];


  // ==================================================
  // Final value saved in Google Sheets
  // ==================================================

  return JSON.stringify(uniqueImages);

})()
}}

