  .map(item => item.json)
  .filter(row => row && row.id !== undefined && row.id !== null);

// بيانات الرسالة النصية الحالية
const context = $('Build Customer Context').first().json;
const event = $('Normalize Freshchat Event').first().json;

// وقت الرسالة النصية الحالية
const currentMessageTime =
  Date.parse(String(event.action_time ?? '')) || Date.now();

// نعتبر الصورة مرتبطة بالنص فقط إذا كانت قبل النص
// وبفارق لا يتجاوز 60 ثانية
const RECENT_WINDOW_MS = 60 * 1000;

function parseImageUrls(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (!value) {
    return [];
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [parsed];
    } catch {
      return [value];
    }
  }

  return [];
}

const recentPendingImages = rows.filter(row => {
  // لازم يكون الصف غير معالج
  if (row.processed !== false) {
    return false;
  }

  // لازم يحتوي فعلًا على صورة
  const images = parseImageUrls(row.image_urls);

  if (images.length === 0) {
    return false;
  }

  // وقت الصورة
  const imageTime = Date.parse(String(row.received_at ?? ''));

  if (!Number.isFinite(imageTime)) {
    return false;
  }

  const difference = currentMessageTime - imageTime;

  // الصورة لازم تكون قبل النص
  // وضمن آخر 60 ثانية فقط
  return (
    difference >= 0 &&
    difference <= RECENT_WINDOW_MS
  );
});

