        context.conversation_internal_id ?? null,
      user_id: context.user_id ?? null,
      message_id: context.message_id ?? null,

      has_recent_pending_image:
        recentPendingImages.length > 0,

      recent_pending_image_count:
        recentPendingImages.length,

      recent_pending_image_ids:
        recentPendingImages.map(row => row.id),

      recent_pending_message_ids:
        recentPendingImages.map(row => row.message_id)
    }
  }
];

