const rows = $input.all().map(item => item.json);

const currentMessageId =
  $('Save Resolution Reply to Buffer').first().json.message_id;

if (rows.length === 0) {
  return [
    {
      json: {
        is_latest_execution: false,
        current_message_id: currentMessageId,
        latest_message_id: null,
        unprocessed_count: 0
      }
    }
  ];
}

// ترتيب الرسائل من الأقدم للأحدث
rows.sort((a, b) => {
  const timeA = new Date(a.message_time || a.created_at).getTime();
  const timeB = new Date(b.message_time || b.created_at).getTime();

  return timeA - timeB;
});

const latestMessage = rows[rows.length - 1];

return [
  {
    json: {
      is_latest_execution:
        latestMessage.message_id === currentMessageId,

      current_message_id: currentMessageId,
      latest_message_id: latestMessage.message_id,
      unprocessed_count: rows.length
    }
  }
];

const rows = $('Get Unprocessed Resolution Replies')
  .all()
  .map(item => item.json);

// نرتب رسائل العميل حسب وقت إرسالها الحقيقي
rows.sort((a, b) => {
  const timeA = new Date(a.message_time || a.created_at).getTime();
  const timeB = new Date(b.message_time || b.created_at).getTime();

  return timeA - timeB;
});

// نجمع النصوص بالترتيب
const combinedMessage = rows
  .map(row => (row.message_text || '').trim())
  .filter(Boolean)
  .join('\n');

// نحتفظ أيضًا بمعلومات القضية الأصلية
